//! Offline verification of tokens Sylphx signs: Auth session tokens and
//! service-to-service invocation tokens. A token is a compact JWS (ES256 or
//! EdDSA) whose key is published in the issuer's JWKS; verification needs no
//! call to Sylphx once the key set is cached.
//!
//! ```no_run
//! # async fn run() -> Result<(), sylphx::auth::verify::VerifyError> {
//! use sylphx::auth::verify::{Verifier, Expect};
//! let verifier = Verifier::new(Expect::issuer("https://api.sylphx.com").audience("my-app"));
//! let claims = verifier.verify("eyJ…").await?;
//! let user = claims.subject();
//! # Ok(()) }
//! ```
