/// Why a token was refused. Every variant means "do not trust this token".
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum VerifyError {
    /// Not three base64url parts, or a part is not the JSON it must be.
    Malformed(String),
    /// `alg` is not ES256 or EdDSA (`none` and HMAC are never accepted).
    Algorithm(String),
    /// No key in the set has the token's `kid` (after one refetch).
    UnknownKey(String),
    /// The signature does not verify.
    Signature,
    /// `exp` is past, `nbf`/`iat` is in the future, or `exp` is missing.
    Expired,
    /// `iss` is not the expected issuer.
    Issuer(String),
    /// None of the token's audiences is expected.
    Audience,
    /// The key set could not be fetched or read.
    Keys(String),
}

impl std::fmt::Display for VerifyError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            VerifyError::Malformed(m) => write!(f, "malformed token: {m}"),
            VerifyError::Algorithm(a) => write!(f, "algorithm {a} is not accepted"),
            VerifyError::UnknownKey(k) => write!(f, "no key {k} in the issuer's key set"),
            VerifyError::Signature => f.write_str("the signature does not verify"),
            VerifyError::Expired => f.write_str("the token is expired or not yet valid"),
            VerifyError::Issuer(i) => write!(f, "unexpected issuer {i}"),
            VerifyError::Audience => f.write_str("the token is not for this audience"),
            VerifyError::Keys(m) => write!(f, "key set: {m}"),
        }
    }
}

