/// What a token must carry.
#[derive(Debug, Clone)]
pub struct Expect {
    pub issuer: String,
    /// Accepted audiences; the token must name at least one. Empty accepts
    /// any audience (only for a caller that checks `aud` itself).
    pub audiences: Vec<String>,
    /// Clock skew tolerated on `exp`, `nbf`, and `iat`.
    pub leeway: Duration,
}

impl Expect {
    pub fn issuer(issuer: impl Into<String>) -> Expect {
        Expect {
            issuer: issuer.into().trim_end_matches('/').to_string(),
            audiences: vec![],
            leeway: Duration::from_secs(60),
        }
    }

    pub fn audience(mut self, audience: impl Into<String>) -> Expect {
        self.audiences.push(audience.into());
        self
    }

    pub fn leeway(mut self, leeway: Duration) -> Expect {
        self.leeway = leeway;
        self
    }
}

/// A verified token's claims.
#[derive(Debug, Clone, PartialEq)]
pub struct Claims(pub Map<String, Value>);

impl Claims {
    pub fn subject(&self) -> Option<&str> {
        self.0.get("sub").and_then(Value::as_str)
    }
    pub fn get(&self, claim: &str) -> Option<&Value> {
        self.0.get(claim)
    }
    pub fn expires_at(&self) -> Option<i64> {
        self.0.get("exp").and_then(Value::as_i64)
    }
}

